  const [slopeMetric, setSlopeMetric] = useState<SlopeMetric>("asiaGrowthPct");

  const mismatch = useMemo(() => mismatchBars(), []);
  const scatter = useMemo(() => {
    const rows = countryScatter(true);
    if (scatterFilter === "all") return rows;
