  const regionBars = useMemo(
    () =>
      REGION_SHARES.map((r) => ({
        short: r.short,
        value: regionMetricValue(r, regionMetric),
        fill: r.fill,
      })),
    [regionMetric],
  );

  const asiaBars = useMemo(
    () =>
      ASIA_SPLIT.map((a) => ({
        short: a.short,
        value:
          asiaLens === "growth"
            ? a.growthContribPct
            : asiaLens === "growthSens"
              ? a.growthSensPct
